'''        // DATABASE_URL (postgres://user:pass@host:port/dbname) overrides the local compose default
        private static string GetDbConnectionString()
        {
            var url = Environment.GetEnvironmentVariable("DATABASE_URL");
            if (string.IsNullOrEmpty(url))
                return "Server=db;Username=postgres;Password=postgres;";

            var uri = new Uri(url);
            var userInfo = uri.UserInfo.Split(':', 2);
            var builder = new NpgsqlConnectionStringBuilder
            {
                Host = uri.Host,
                Port = uri.IsDefaultPort ? 5432 : uri.Port,
                Username = Uri.UnescapeDataString(userInfo[0]),
                Password = userInfo.Length > 1 ? Uri.UnescapeDataString(userInfo[1]) : null,
                Database = uri.AbsolutePath.Trim('/'),
            };
            return builder.ConnectionString;
        }

        // REDIS_URL (redis://[user]:pass@host:port) overrides the local compose default
        private static string GetRedisConfiguration()
        {
            var url = Environment.GetEnvironmentVariable("REDIS_URL");
            if (string.IsNullOrEmpty(url))
                return "redis";

            var uri = new Uri(url);
            var config = $"{uri.Host}:{(uri.IsDefaultPort ? 6379 : uri.Port)}";
            var userInfo = uri.UserInfo.Split(':', 2);
            if (userInfo.Length > 1 && userInfo[1].Length > 0)
                config += $",password={Uri.UnescapeDataString(userInfo[1])}";
